<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\{EWallet,FeeSetting,Order,WalletTransaction}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class SettlementController extends Controller { public function settle(Request $r,Order $order){abort_unless((int)$order->customer_id===(int)$r->user()->id,403,'Hanya pemilik order yang dapat menyelesaikan transaksi');if(!in_array($order->status,['DELIVERED','SHIPPED'],true))return response()->json(['message'=>'Order belum siap diselesaikan'],422);$result=DB::transaction(function()use($r,$order){$o=Order::whereKey($order->id)->lockForUpdate()->first();if($o->status==='COMPLETED')return $o;$commission=FeeSetting::value('app_commission',1000);$courierFee=$o->courier_fee?:FeeSetting::value('courier_fee',1000)*(int)($o->item_count?:1);$goods=(int)$o->item_cost+(int)$o->shipping_cost+$courierFee;$total=$goods+$commission;$customer=EWallet::where('user_id',$r->user()->id)->lockForUpdate()->first();$recipientId=$o->courier_id?:$o->traveler_id;$recipient=$recipientId?EWallet::where('user_id',$recipientId)->lockForUpdate()->first():null;if(!$customer||$customer->balance<$total||!$recipient)return null;$customer->decrement('balance',$total);$recipient->increment('balance',$goods);WalletTransaction::create(['e_wallet_id'=>$customer->id,'type'=>'ORDER_SETTLEMENT','debit'=>$total,'credit'=>0,'amount'=>$total,'fee'=>$commission,'description'=>'Pembayaran order dan biaya platform','reference'=>'ORDER-'.$o->id]);WalletTransaction::create(['e_wallet_id'=>$recipient->id,'type'=>'ORDER_EARNING','debit'=>0,'credit'=>$goods,'amount'=>$goods,'fee'=>0,'description'=>'Pendapatan order','reference'=>'ORDER-'.$o->id]);$o->update(['commission'=>$commission,'courier_fee'=>$courierFee,'status'=>'COMPLETED']);return $o->fresh();});return $result?response()->json(['order'=>$result,'total'=>$result->item_cost+$result->shipping_cost+$result->courier_fee+$result->commission]):response()->json(['message'=>'Saldo customer atau wallet penerima tidak mencukupi'],422);}}
